                                   const float* val, const float* x, 
                                   float* y, int num_rows) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row >= num_rows) return;

    int start = row_ptr[row];
    int end = row_ptr[row + 1];
    float sum = 0.0f;

    // Process in chunks of 4 using float4/int4 to maximize 128-byte transaction efficiency
    // Assumes val and col_idx are allocated and padded to 128-byte boundaries
    int i = start;
    while (i <= end - 4) {
        float4 val_vec = reinterpret_cast<const float4*>(&val[i])[0];
        int4 idx_vec = reinterpret_cast<const int4*>(&col_idx[i])[0];

        sum += val_vec.x * x[idx_vec.x];
        sum += val_vec.y * x[idx_vec.y];
        sum += val_vec.z * x[idx_vec.z];
        sum += val_vec.w * x[idx_vec.w];
        i += 4;
    }

    // Handle remaining elements
    while (i < end) {
        sum += val[i] * x[col_idx[i]];
        i++;
    }
    y[row] = sum;
}
