    }

    mutating func write(_ data: [UInt8]) {
        for byte in data {
            buffer[head] = byte
            head = (head + 1) % size
        }
    }
}
```
This pointer-based wrap-around system ensures that once the flash partition is full, the write pointer resets to the start, preventing partition exhaustion and reducing the frequency of full erase cycles.

